public class Main {
    static boolean isVowel(char c) {
        return "aeiou".indexOf(Character.toLowerCase(c)) >= 0;
    }

    public static void main(String[] args) {
        int count = 0;
        for (char c : "Education".toCharArray()) {
            if (isVowel(c)) {
                count++;
            }
        }
        System.out.println(count);
    }
}
